onSubmit:
{{(() => {
     const address = (NewPickupAddressInput.text || "").trim();
     if (address.length < 4) {
       showAlert("Въведете адрес преди да търсите", "warning");
       return;
     }
     GeocodeNewPickupAddress.run()
       .then(() => {
         if (GeocodeNewPickupAddress.data?.results?.length > 0) {
           LocationManager.updateNewPickupFromGeocode();
         } else {
           showAlert("Адресът не е намерен — проверете изписването", "warning");
         }
       })
       .catch(() => showAlert("Търсенето на адреса не мина. Опитайте пак.", "error"));
   })()}}

onTextChanged:
{{(() => {
     // Typing invalidates whatever was found for the previous text. The search itself
     // is the "Търси" button beside this field (or Enter) - see 2026-09-19.
     // The warehouse's own line needs no search - it is where we collect from.
     const w = (BoWarehouse.data || [])[0];
     if (w && w.address && NewPickupAddressInput.text === w.address) {
       NewPickupLatHidden.setValue(String(w.lat));
       NewPickupLngHidden.setValue(String(w.lng));
       return;
     }
     // Only when the text really differs from what the pin was found for: this handler can
     // fire after a quick search and must not wipe its result (2026-10-02).
     const typed = (NewPickupAddressInput.text || "").trim();
     if ((NewPickupLatHidden.text || NewPickupLngHidden.text) && typed !== (appsmith.store.newPickupSearchedText || "")) {
       NewPickupLatHidden.setValue("");
       NewPickupLngHidden.setValue("");
     }
   })()}}
